package com.cenedu.backend.domain.problem.authoring.semantic.materialization;
import com.cenedu.backend.domain.problem.authoring.port.ProblemSemanticMaterializer; import com.cenedu.backend.domain.problem.authoring.semantic.model.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.*; import com.cenedu.backend.domain.problem.authoring.semantic.validation.*; import java.util.*;
public final class DefaultProblemSemanticMaterializer implements ProblemSemanticMaterializer { private final ProblemSemanticModelValidator validator=new ProblemSemanticModelValidator(new SemanticUnitAndBoundsValidator(),new SemanticConstraintValidator(),new SemanticAssertionValidator()); public MaterializedProblem materialize(ProblemSemanticModelV1 m){if(!m.diagrams().isEmpty())throw new SemanticMaterializationException("DiagramSpecV1 family is not registered");validator.validate(m);var e=new SemanticComputationEngine().evaluate(m);var snapshot=new SemanticSnapshotFactory().create(m,e.values());var values=new LinkedHashMap<String,String>();e.values().forEach((k,v)->values.put(k,v.canonicalValue()));return new MaterializedProblem(snapshot,List.of(),new SemanticMaterializationReport(1,e.topologicalOrder(),Map.copyOf(values),Set.of(),Set.of()));} }
